using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.JNT.JuntaDetalleArchivos;using GraphApi.Services.JNT.JuntaDetalleArchivos;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.JNT.JuntaDetalleArchivos{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de JuntaDetalleArchivos: creación, actualización y eliminación.")]    public class JuntaDetalleArchivosMutation    {        [Authorize]        [GraphQLName("createJuntaDetalleArchivos")]        [GraphQLDescription("Crea un nuevo JuntaDetalleArchivo usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadJuntaDetalleArchivos> CreateJuntaDetalleArchivosAsync(            [GraphQLDescription("Datos necesarios para crear el JuntaDetalleArchivo.")]            clCreateJuntaDetalleArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalleArchivo.")]            IJuntaDetalleArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateJuntaDetalleArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateJuntaDetalleArchivos")]        [GraphQLDescription("Actualiza los campos especificados de un JuntaDetalleArchivo existente.")]        public async Task<clReadJuntaDetalleArchivos?> UpdateJuntaDetalleArchivosAsync(            [GraphQLDescription("Datos del JuntaDetalleArchivo a actualizar.")]            clUpdateJuntaDetalleArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalleArchivo.")]            IJuntaDetalleArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateJuntaDetalleArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteJuntaDetalleArchivos")]        [GraphQLDescription("Elimina un JuntaDetalleArchivo por su ID.")]        public async Task<bool> delJuntaDetalleArchivosAsync(            [GraphQLDescription("ID del JuntaDetalleArchivo a eliminar.")]            int nJuntaDetalleArchivosID,            [Service]            [GraphQLDescription("Servicio para operaciones de JuntaDetalleArchivo.")]            IJuntaDetalleArchivosService objService        )        {            return await objService.DeleteJuntaDetalleArchivos(nJuntaDetalleArchivosID);        }    }}